const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
if (!token) throw new Error('Invalid or missing session token.');
// The token is only a lookup key. Who the caller is comes from the sessions table (Verify Session) — never from
// the token's own text (the old token_<id>_<n> format could be forged to impersonate any user).
return [{ json: { token, authHeader: 'Bearer ' + token } }];

const requester = $input.first().json;
if (!requester.id || !requester.active) throw new Error('Invalid session.');
// The import can add hundreds of contacts and sends outreach email, so it is admin-only.
if (requester.role !== 'admin') throw new Error('Admin access required to import leads.');

const body = $('Webhook: import-maps-leads').first().json.body || {};
const clean = (v) => (typeof v === 'string' || typeof v === 'number' ? String(v) : '').replace(/[\u0000-\u001f\u007f]/g, ' ').trim();
const searchQuery = clean(body.search_query);
const location = clean(body.location);
if (!searchQuery) throw new Error('search_query is required (for example roofing contractors).');
if (!location) throw new Error('location is required (for example Austin, TX).');
if (searchQuery.length > 200 || location.length > 200) throw new Error('search_query and location must be 200 characters or fewer.');

let maxResults = parseInt(body.max_results, 10);
if (!Number.isInteger(maxResults) || maxResults <= 0) maxResults = 30;
maxResults = Math.min(maxResults, 100);

return [{ json: { requesterId: requester.id, searchQuery, location, maxResults } }];

const items = $input.all().map((i) => i.json).filter((p) => p && p.title && p.placeId);
const ctx = $('Validate Payload').first().json;

return [{
  json: {
    requesterId: ctx.requesterId,
    scraped: items.length,
    names: items.map((p) => p.title),
    websites: items.map((p) => p.website || ''),
    phones: items.map((p) => p.phoneUnformatted || p.phone || ''),
    streets: items.map((p) => p.street || p.address || ''),
    cities: items.map((p) => p.city || ''),
    states: items.map((p) => p.state || ''),
    countries: items.map((p) => p.countryCode || ''),
    placeIds: items.map((p) => p.placeId),
    mapsUrls: items.map((p) => p.url || ''),
    ratings: items.map((p) => (p.totalScore != null ? Number(p.totalScore) : null)),
    reviewCounts: items.map((p) => (p.reviewsCount != null ? Number(p.reviewsCount) : null)),
    categories: items.map((p) => p.categoryName || ''),
  },
}];

const imported = $input.all().length;
const scraped = $('Map Apify Results').first().json.scraped;
return [{ json: { success: true, scraped, imported, skipped_duplicates: scraped - imported } }];

const key = $input.first().json.api_key;
if (!key) throw new Error('Apify is not connected — add an API key in Settings > Integrations.');
const ctx = $('Validate Payload').first().json;
return [{ json: { ...ctx, apifyKey: key } }];

function safeEnv(key) { try { return $env[key] || ''; } catch (e) { return ''; } }
const contacts = $('Look Up Contact For Outreach').all();
const templates = $('Look Up Outreach Template').all();
const companies = $('Get Company Name (Outreach)').all();
// Business names and scraped contact names are third-party text (Google Maps / a website), so they are
// HTML-escaped in the body and kept to one plain line in the subject.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const plain = (s) => String(s ?? '').replace(/[\r\n]+/g, ' ');
// Same placeholders the template editor offers: company.name is the PROSPECT's business, user.company_name is ours
// (the older business_name / first_name / company_name spellings keep working).
function fill(t, contact, ours, enc) {
  const first = contact.first_name || 'there';
  const map = {
    'contact.first_name': first, 'first_name': first,
    'company.name': contact.business_name || 'your company', 'business_name': contact.business_name || 'there',
    'user.company_name': ours, 'company_name': ours,
  };
  return (t || '').replace(/\{\{\s*([\w.]+)\s*\}\}/g, (m, k) => (Object.prototype.hasOwnProperty.call(map, k) ? enc(map[k]) : ''));
}
const results = [];
for (let i = 0; i < contacts.length; i++) {
  const contact = contacts[i].json;
  const template = (templates[i] || templates[0] || {}).json;
  const companyName = ((companies[i] || companies[0] || {}).json || {}).company_name || 'Us';
  if (!template || !template.subject) continue;
  const unsubUrl = safeEnv('FRONTEND_BASE_URL') + '/unsubscribe/' + encodeURIComponent(contact.unsubscribe_token || '');
  const footer = `<br><br><span style="font-size:11px;color:#94a3b8">Don't want these emails? <a href="${unsubUrl}">Unsubscribe</a></span>`;
  results.push({ json: { to: contact.email, subject: fill(template.subject, contact, companyName, plain), htmlBody: fill(template.body, contact, companyName, esc).replace(/\n/g, '<br>') + footer, contactId: contact.contact_id, companyName } });
}
return results;

const r = $input.first().json;
if (!r.valid || !r.active) throw new Error('Invalid session.');
return [{ json: { id: r.userId, name: r.user?.name, role: r.role, active: r.active } }];

// Company branding + rep signature for outgoing HTML emails. Everything is off until an admin switches on
// "Add company branding and signatures to emails" in Settings > Company Profile (company_profile.email_branding_enabled).
function buildBrandParts(branding, signatureText, companyName) {
  const b = branding || {};
  const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  const on = b.email_branding_enabled === true;
  if (!on) return { on: false, header: '', footer: '', sig: '', sigText: '' };
  const color = /^#[0-9a-fA-F]{6}$/.test(b.brand_color || '') ? b.brand_color : '#2563EB';
  const logo = /^https?:\/\//i.test(b.logo_url || '')
    ? '<img src="' + esc(b.logo_url) + '" alt="' + esc(companyName) + '" style="max-height:56px;max-width:200px;display:block;margin-bottom:6px">' : '';
  const name = companyName ? '<div style="font-size:18px;font-weight:bold;color:' + color + '">' + esc(companyName) + '</div>' : '';
  const header = (logo || name) ? '<div style="padding-bottom:12px;margin-bottom:16px;border-bottom:3px solid ' + color + '">' + logo + name + '</div>' : '';
  const lines = [b.address, b.phone, b.website, b.email].filter(Boolean).map(esc);
  const note = b.email_footer_note ? '<div style="margin-top:6px">' + esc(b.email_footer_note).replace(/\n/g, '<br>') + '</div>' : '';
  const footer = (lines.length || note)
    ? '<div style="margin-top:24px;padding-top:12px;border-top:1px solid #e2e8f0;font-size:12px;color:#64748b">' + (lines.length ? '<div>' + lines.join(' &middot; ') + '</div>' : '') + note + '</div>' : '';
  const sigText = signatureText && String(signatureText).trim() ? String(signatureText).trim() : '';
  const sig = sigText ? '<div style="margin-top:16px">' + esc(sigText).replace(/\n/g, '<br>') + '</div>' : '';
  return { on: true, header, footer, sig, sigText };
}

// Apply Branding — works out this email's company header and footer and adds them to the item as __brandHeader and
// __brandFooter; the Send node then wraps its own HTML with them. Strictly additive and fail-safe: if branding is
// switched off or anything at all goes wrong, the item passes through untouched and the email goes out exactly as before.
const item = $input.item;
try {
  const sd = $getWorkflowStaticData('global');
  const now = Date.now();
  let b = sd.__brandCache && now - sd.__brandCache.t < 60000 ? sd.__brandCache.data : null;
  if (!b) {
    let base = 'http://localhost:5678';
    try { if ($env.N8N_INTERNAL_URL) base = $env.N8N_INTERNAL_URL; } catch (e) { /* env access blocked */ }
    const r = await this.helpers.httpRequest({ url: base.replace(/\/$/, '') + '/webhook/get-email-branding', method: 'GET', json: true, timeout: 5000 });
    b = r && typeof r === 'object' ? r : {};
    sd.__brandCache = { t: now, data: b };
  }
  if (b.email_branding_enabled === true) {
    const parts = buildBrandParts(b, '', b.company_name || '');
    return { json: { ...item.json, __brandHeader: parts.header, __brandFooter: parts.footer }, binary: item.binary };
  }
} catch (e) { /* branding is optional */ }
return item;
